package com.fincore.fincore.transaction; import java.time.Instant; import java.math.BigDecimal; import java.util.Optional; import org.springframework.data.domain.*; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; public interface TransactionRepository extends JpaRepository<FinanceTransaction,Long>{Page<FinanceTransaction> findAllByUserId(Long userId,Pageable p);Optional<FinanceTransaction> findByIdAndUserId(Long id,Long userId);@Query("select coalesce(sum(t.amount),0) from FinanceTransaction t where t.user.id=:uid and lower(t.category)=lower(:category) and t.transactionType=com.fincore.fincore.transaction.TransactionType.EXPENSE and t.occurredAt>=:start and t.occurredAt<:end") BigDecimal spent(@Param("uid")Long uid,@Param("category")String category,@Param("start")Instant start,@Param("end")Instant end);}
